-- 5011 🏋️ Exercises from the book "kindle-soccer-modern-tactics" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'kindle-soccer-modern-tactics');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Back four closing down and cover', 'defending', 'passive', 'out_of_possession', 6, 9, '1.1 Coming out and control of the opponent in possession', NULL, 'Back four learns who presses the ball carrier and how the others cover (one, two or three cover lines) as the ball moves.', 'Back four in their defensive third with four servers A, B, C, D spread across the field in front of them; coach points to the server holding the ball.', 'Servers pass the ball among themselves on the coach''s whistle; the nearest defender steps out to pressure the receiver while the others drop diagonally into cover or form a pyramid when the ball is central. Check marking and cover after every pass.', 'Pressing defender approaches fast while the ball travels and stops just before the receiver takes it.', 'Choose single, double or triple cover depending on your defenders'' 1v1 ability. Then servers pass randomly; then add one or two passive forwards on the back line who only shuffle sideways and must be marked (tight if the carrier cannot see goal, looser if he can).', 'Cover diagonally behind the presser; stay goal-side and see ball and man; don''t get too close in case of a switch; mark tight when the carrier has his back to goal.', '4 defenders + 4 servers (+1-2 passive forwards)', 8, 10, 'Half field', NULL, NULL, NULL, true, false, false, NULL, 10),
  ('Handing over marking along the back line', 'defending', 'passive', 'out_of_possession', 10, 10, '1.2 Passing the marking duties from one defender to the next', NULL, 'Pass a dribbler on from defender to defender as he crosses zones without leaving a gap.', 'Back four on a line of cones with one attacker A dribbling across their front.', 'A dribbles from one defender''s zone into the next; the next defender calls and takes him over while the first returns to cover. A can dribble back and forth across all four zones.', NULL, 'Add one then two passive attackers off the ball; carrier alternately faces goal (double cover) or not (single cover line); the line steps up together when the ball moves away from goal.', 'Never hand over too early; the receiving defender stays close and covers until the switch; keep short distances; never stand flat in one line; talk because the marker cannot see behind him.', '4 defenders + 1-3 attackers', 5, 7, NULL, NULL, NULL, NULL, true, false, false, NULL, 20),
  ('Stopping runs in behind the back four', 'defending', 'opposed', 'out_of_possession', 11, 11, '1.3 Neutralizing deep penetrating runs', NULL, 'Deal with an attacker cutting in behind the line from a wide or central carrier.', 'Back four with a wide carrier A and a runner E between the defenders; more servers B, C in midfield.', 'A dribbles and plays E who cuts between two defenders; the defender who can see the run tracks slightly ahead of E or lets him go offside, called by the last defender. If A dribbles inside instead, defenders swap marks or cross over.', NULL, 'Carrier delays the pass on purpose; repeat with A cutting between different pairs and with B or C carrying centrally and various runners.', 'Track the runner a step ahead, not level; the defender facing the run takes it; last defender calls offside; line steps up together.', '4 defenders + 2-4 attackers', 6, 8, NULL, NULL, NULL, NULL, true, false, true, NULL, 30),
  ('Defending one-twos against the back four', 'defending', 'opposed', 'out_of_possession', 12, 12, '1.4 Neutralizing triangular passing', NULL, 'Back line reads and breaks up wall passes played around a defender.', 'Back four with a carrier A out wide and a wall player E; later carrier B in central midfield.', 'A runs at the defender, plays a one-two with E and runs behind; the defender turns and drops to cut the return while the others shift. Centrally, B dribbles at a centre back and calls E for the triangle while neighbours drop in a chain.', NULL, 'Repeat with E on the right and left and with B or C carrying so every defender faces triangles.', 'Defender drops as a moving shield and does not stop; nearest defender to E steps in only if he can win it; beware the carrier keeping the ball near the box.', '4 defenders + 2-3 attackers', 6, 7, NULL, NULL, NULL, NULL, true, false, true, NULL, 40),
  ('Defending the overlap out wide', 'defending', 'opposed', 'out_of_possession', 13, 13, '1.5 Neutralizing overlapping', NULL, 'Full back delays a wide 2v1 overlap until help arrives.', 'Back four with wide attacker A and overlapping attacker B on one flank.', 'B passes to A and overlaps; the full back backs off to buy time until the nearest centre back slides across to take A, then the full back picks up B.', NULL, 'Run on both flanks.', 'Don''t let the carrier get too close; keep sight of carrier and overlapper; delay when outnumbered and only tackle when he overstretches or B is offside.', '4 defenders + 2 attackers', 6, 6, NULL, NULL, NULL, NULL, true, false, true, NULL, 50),
  ('Back line drops for long balls and flick-ons', 'defending', 'opposed', 'out_of_possession', 14, 15, '1.6 Neutralizing shots and headers', NULL, 'Back four drops correctly for balls played over the top and covers flick-ons from a target forward.', 'Back four with two forwards C and D on their line; four midfield passers A to B across the middle; big cones mark the flanks.', 'Midfielders pass across without attacking; the line slides and drops on vertical dribbles, short or long balls, marking C and D tighter or looser depending on whether the carrier sees goal. Then forwards go deep for the ball and the carrier may shoot; a high ball to a forward is flicked on to a runner.', NULL, 'Forwards make early runs (go with them then return); add runners D and E chasing flick-ons from either side.', 'Drop with a sideways cross-step ready to turn, not a straight backpedal; engaged defender attacks the ball while others secure marking; don''t drop too early.', '4 defenders + 4 midfielders + 2-3 forwards', 10, 11, NULL, NULL, NULL, NULL, true, false, true, NULL, 60),
  ('Stopping the forward turning on the ball', 'defending', 'opposed', 'out_of_possession', 16, 16, '1.7 Neutralizing penetrating passes', NULL, 'Prevent a forward receiving to feet from turning and running at the line.', 'Back four with forward C in front of them; midfield passers A, B pass across the middle.', 'As the midfielders pass, C fakes a run behind and comes short to receive; the nearest centre back closes him while the ball travels and the rest of the line tucks in behind.', NULL, NULL, 'Close quickly, stop on one side with an arm out to feel him; deny lean and pivot; tackle when he is half turned; line stays compact behind the presser.', '4 defenders + 3 attackers', 7, 7, NULL, NULL, NULL, NULL, true, false, true, NULL, 70),
  ('Back line steps up on back passes', 'defending', 'opposed', 'out_of_possession', 17, 17, '1.8 Conduct for back passes', NULL, 'Squeeze up as a unit when the opponent plays backwards and stop before the receiver controls.', 'Back four against four midfield carriers and two forwards on their line; supporting players A just behind the carriers and A1 10-12 yards back in the other half, each able to slide across the width.', 'Carriers move the ball and the line presses and covers; on a pass back to A (short) the line holds, on a pass to A1 (long) the line steps up and stops in time, keeping the forwards marked. A1 receiving ends the rep.', NULL, 'Add two attackers on the line who must not be lost on the step-up; A or A1 then plays a short or long ball forward.', 'Move while the ball is travelling, set before it arrives; stand side-on and re-read; keep marking while stepping up.', '4 defenders + 4 carriers + 2 forwards + 2 servers', 12, 12, NULL, NULL, NULL, NULL, true, false, true, NULL, 80),
  ('Back line drops and compacts with keeper', 'defending', 'opposed', 'out_of_possession', 18, 18, '1.9 Position of the line', NULL, 'Drop and close up when there is too much space behind, before pressing the dribbler.', 'Back four facing four attackers spread across the field near halfway; goalkeeper in goal.', 'A dribbles wide near midfield; the line drops and narrows, then the first defender steps out and hands the marking on with each change of direction. Repeat with the carrier central and on the other side; the keeper starts high and drops with the line.', NULL, 'Add two attackers on the line; then add runners making triangles and overlaps behind the line as it closes up.', 'Only press from a good, compact position; otherwise retreat towards the keeper.', '4 defenders + GK + 4-6 attackers', 9, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 90),
  ('Defending a man down in the back line', 'defending', 'overload', 'out_of_possession', 19, 20, '1.10 When the defensive line is in a situation of numerical inferiority', NULL, 'Three defenders delay and recover when one teammate is out of position.', 'One defender starts upfield behind carrier A; three defenders on the line against forwards B, C, D.', 'A dribbles; the out-of-position defender sprints back on a diagonal inside line while the other three retreat and close up, then the line presses and swaps marks. Variant: defender does not recover and the three accept the overload, waiting for a heavy touch or a forward running offside.', NULL, 'Rotate which defender is missing; ball on right, left and centre.', 'Recovery run goes diagonally inside towards goal; delay and wait for help; pounce on a heavy touch; the defender who sees the picture calls the marks; the keeper can sweep.', '4 defenders (one recovering) + 4 attackers', 8, 8, NULL, NULL, NULL, NULL, true, false, true, NULL, 100),
  ('Marking in the box against crosses', 'defending', 'opposed', 'out_of_possession', 21, 21, '1.11 Marking against crosses', NULL, 'Switch from zonal to man marking around the penalty area when a cross comes.', 'Back four and goalkeeper; attackers A, B, C, D plus a wide player A2 deep on the flank.', 'A swaps with B, plays wide to A2 who crosses; the forwards attack the box and are marked man to man while one defender shields the crosser''s side. Attackers try to score, defenders to clear.', NULL, NULL, 'Hand over marks only if there is time, otherwise go man to man; if you must choose, watch your man rather than the ball.', '4 defenders + GK + 5 attackers', 10, 10, NULL, NULL, NULL, NULL, true, true, true, NULL, 110),
  ('4v4 plus keeper with deep server', 'phase_of_play', 'opposed', 'out_of_possession', 22, 22, '1.12 A few training exercises: 4 v 4 + G with one or more back-ups', NULL, 'Back line reacts to a deep playmaker who can shoot, pass short or recycle.', 'As the 4v4+G, with server A behind the attacking line, moving across the width, near or far.', 'A feeds the attack and then chooses a long shot, short pass or dribble back left or right, facing goal or not; the back line responds to each.', 'Defenders counter into midfield on winning the ball.', 'Add one then two attackers to the defensive line.', NULL, '4v4+GK+1 server', 10, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 120),
  ('4v4 plus keeper with offside trap', 'phase_of_play', 'opposed', 'out_of_possession', 22, 23, '1.12 A few training exercises: 4 v 4 + G with offside trap and counterattack', NULL, 'Back four defends a live 4v4 using the offside trap and counters on winning it.', 'Back four and goalkeeper against four attackers in the defensive half.', 'Coach serves to one of the four attackers who try to score; if the defenders win it they must dribble or pass it into midfield unhindered.', 'Defenders score by carrying or receiving in midfield.', 'Add one attacker (5v4+G), then two (6v4+G); repeat all with the line starting just before halfway; start with the line near the box and the keeper throwing or kicking to an attacker so defenders react to balls from behind.', 'Alternate with full games so the situations transfer.', '4v4+GK (to 6v4+GK)', 9, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 130),
  ('4v3 plus keeper with recovering defender', 'phase_of_play', 'overload', 'out_of_possession', 22, 23, '1.12 A few training exercises: 4 v 3 + G with one player coming back', NULL, 'Three defenders hold out four attackers while a fourth recovers, then counter.', 'Three defenders and keeper against four attackers; fourth defender starts upfield.', 'A dribbles and the fourth defender recovers at the same moment; attackers try to score, defenders win it and carry or receive in midfield unopposed. Repeat from all positions.', 'Defenders score by reaching midfield with the ball.', 'Variant without the recovering defender: three defenders accept the overload and solve it.', 'Delay until help arrives.', '4v3+GK (+1 recovering)', 8, 9, NULL, NULL, NULL, NULL, true, true, true, NULL, 140),
  ('Seven plus keeper vs eight attackers', 'phase_of_play', 'overload', 'out_of_possession', 28, 28, 'Lippi diagram 4', 'Lippi (Juventus)', 'Defensive block of 3 defenders and 4 midfielders defends an overload and counters to goals past halfway.', 'Goalkeeper, 3 defenders and 4 midfielders in their half against 8 or 9 attackers; small goals set beyond the halfway line.', 'Attackers try to score; if the seven win the ball they attack the small goals beyond midfield.', NULL, 'Set the seven in a defending or attacking shape depending on the aim; position the defence to match expected opponents.', NULL, '7+GK v 8-9', 16, 17, 'Half field', NULL, NULL, NULL, true, true, true, NULL, 150),
  ('7v7 in a 3-2-2 shape', 'small_sided_game', 'opposed', 'in_possession', 28, 28, 'Lippi diagram 5', 'Lippi (Juventus)', 'Train the two forwards and the attacking midfielder linking up in the final third.', '7v7 in a narrow area in one half, both teams in a 3-2-2.', 'Play a game; width is provided by the backs or the wide midfielders.', NULL, NULL, NULL, '7v7', 14, 14, NULL, NULL, NULL, NULL, true, false, true, NULL, 160),
  ('3v3 closing down and cover', 'small_sided_game', 'opposed', 'out_of_possession', 28, 29, 'Lippi diagram 6', 'Lippi (Juventus)', 'Practise pressing the ball carrier and covering in a small game.', '3v3 in a small marked box near halfway.', 'Play 3v3; defenders close down the carrier and cover each other.', NULL, NULL, NULL, '3v3', 6, 6, NULL, NULL, NULL, NULL, false, false, true, NULL, 170),
  ('Midfield three or five pressing shape', 'defending', 'passive', 'out_of_possession', 32, 33, '2.2 Midfield with 3 or 5 players', NULL, 'Midfield unit learns its press and cover positions for a wide and a central ball.', 'Midfield line of 3 (or 5) facing a line of opposing passers around halfway.', 'Ball is moved between the passers; with a wide ball the near midfielder presses and the rest cover diagonally, with a central ball the centre midfielder steps out and the others form the triangle. Same approach for a five-man midfield.', NULL, 'Midfield of 5 against wide and central ball.', 'Same methodology as the back four, but no offside trap.', '3 or 5 midfielders + 3-4 passers', 6, 9, NULL, NULL, NULL, NULL, false, false, false, NULL, 180),
  ('Back four shadow defending vs passing line', 'defending', 'passive', 'out_of_possession', 40, 41, 'Diagram 33', NULL, 'Back four learns to shift, mark the forwards and cover together as the ball moves across an opposing line.', 'Half-pitch towards one goal: a line of 4 opposing players passing the ball side to side in front of the back four; two forwards (A and B) for the centre backs to mark and cones out wide standing in for opposing wingers.', 'The 4 opponents move the ball across; the centre backs mark the two forwards while the full backs close the gap to the cone that represents the wide man on the ball side. Then the player on the ball is allowed to either face up or not see the goal, so the unit must choose between pressing and covering.', NULL, 'Add defending against shots, through balls and back passes; add midfielders in front of the defence, then the forwards; after winning the ball or a back pass, trigger a counter-attacking restart suited to the formation or the opponent.', 'Defenders aggressive when the ball carrier can see goal, otherwise focus on cover; keep correct distances to each other for marking forwards and the wide opponent; the action does not end when the ball is won - be ready to restart at once.', '4 defenders v 2 forwards + 4 passers', 10, NULL, 'half pitch', NULL, NULL, NULL, true, false, true, NULL, 190),
  ('Full-back overlap and cross, 4-4-2', 'combination', 'unopposed', 'in_possession', 72, 72, '4.1 (diagram 57)', NULL, 'Rehearse a 4-4-2 build-up where the full-back overlaps the wide midfielder and delivers a cross into a full box.', '4-4-2 shape on the full pitch; back four circulate the ball, wide midfielder (8) drifts wide, forwards and the far-side/central midfielders ready to attack the box.', 'Defenders pass across the line, each receiving after a dummy move; left-back plays into the wide midfielder and overlaps; 8 finds a forward or the attacking midfielder, who complete a triangle so the full-back can cross to the far winger, a forward and the central midfielder arriving at the edge of the box.', NULL, 'Variation: 8 is pressed tightly and cannot play forward first time, so the attacking midfielder drops to support and plays the full-back in behind (diagram 57b).', 'Repeat on both flanks; receive after a feint.', '10 outfield (4-4-2)', NULL, NULL, 'full pitch (shadow play in formation)', NULL, NULL, NULL, true, false, true, NULL, 200),
  ('Wide midfielder inside, full-back outside', 'combination', 'unopposed', 'in_possession', 73, 73, '4.2 (diagram 58)', NULL, 'Wide midfielder and full-back rotate (one in, one out) to create a receiving option off the centre-back.', '4-4-2 shape; ball starts with the back line moving to a centre-back (6); wide midfielder 8 and left-back 3 both start wide.', 'As the ball reaches the centre-back, 8 cuts inside and 3 runs into the vacated wide lane. If 8 receives he combines with the near forward, shoots, or plays through for a diagonal run or a third-man run from midfield; if 3 receives he triangles with 8 to cross or 8 overlaps him.', NULL, 'Options: deep pass if the two strikers criss-cross; 8 can overlap 3 instead.', 'Timing: move when the passer can see you.', NULL, NULL, NULL, 'full pitch (shadow play in formation)', NULL, NULL, NULL, true, false, true, NULL, 210),
  ('Lay-off for central midfielder runs', 'combination', 'unopposed', 'in_possession', 74, 74, '4.3 (diagram 59)', NULL, 'Create a shooting or through-ball chance for a central midfielder after a striker lays the ball back.', '4-4-2 shape; right-back 2 in possession, right midfielder 7 high and wide, two forwards, two central midfielders.', 'With 2 on the ball, 7 runs in behind and the nearest forward checks short to receive; he lays off to central midfielder 5, while 9 cuts in and the other central midfielder 10 runs into the freed space; 5 then plays to 9 or 10 (or shoots).', NULL, NULL, NULL, NULL, NULL, NULL, 'full pitch (shadow play in formation)', NULL, NULL, NULL, true, false, true, NULL, 220),
  ('Striker checks short to support wide midfielder', 'combination', 'unopposed', 'in_possession', 75, 75, '4.4 (diagram 60)', NULL, 'Forward comes short to give a wide midfielder a combination when he is faced up by a defender.', 'Attacking half: attacking midfielder 10 central, wide midfielder 8 wide, two forwards.', '10 plays to 8, who has a defender in front of him, so the nearest forward drops to make a triangle with 8 while the other forward prepares to cut in behind.', NULL, NULL, 'Support angle for the man under pressure; second striker times the run.', NULL, NULL, NULL, 'full pitch (shadow play in formation)', NULL, NULL, NULL, true, false, true, NULL, 230),
  ('Central and wide midfielder swap positions', 'combination', 'unopposed', 'in_possession', 76, 76, '4.5 (diagram 61)', NULL, 'Use a positional rotation between a central and a wide midfielder to lose a marker.', 'Midfield line around halfway: right wide midfielder 7 on the ball, central midfielders 5 and 10, left wide midfielder 8.', '7 plays back into 5; 10 pushes forward and, to shake off his marker, swaps places with 8 so one of them is free to receive the next pass.', NULL, NULL, NULL, NULL, NULL, NULL, 'full pitch (shadow play in formation)', NULL, NULL, NULL, true, false, true, NULL, 240),
  ('Forward and wide midfielder swap positions', 'combination', 'unopposed', 'in_possession', 77, 77, '4.6 (diagram 62)', NULL, 'Rotation between a marked wide midfielder and the near forward to free a receiver for the full-back.', 'Left flank: left-back 3 in possession, wide midfielder 8 and near forward 11, both marked.', '8 and 11 exchange positions as 3 prepares to pass; 3 then plays either into 8 cutting inside or into 11 running outside.', NULL, NULL, NULL, NULL, NULL, NULL, 'full pitch (shadow play in formation)', NULL, NULL, NULL, true, false, true, NULL, 250),
  ('Outer pair movements: full-back and winger', 'combination', 'unopposed', 'in_possession', 78, 78, '4.7', NULL, 'Rehearse the rotations of the wide pair (full-back plus wide midfielder) in a 4-4-2 when a ball-playing centre-back has the ball.', '4-4-2; a centre-back able to play long is in possession; work on the full-back and wide midfielder on one side.', 'The pair rehearse set rotations: one drops deep while the other goes forward; one goes wide while the other comes inside; or the full-back runs deep and wide while the midfielder cuts towards goal; or the full-back cuts inside while the midfielder halts and widens.', NULL, NULL, 'One player always balances the other''s movement.', NULL, NULL, NULL, 'full pitch (shadow play in formation)', NULL, NULL, NULL, false, false, true, NULL, 260),
  ('4-3-3 build-up via full-back from goalkeeper', 'passing_unopposed', 'unopposed', 'in_possession', 79, 79, '4.8 (diagram 63)', NULL, 'Play out from the goalkeeper in a 4-3-3, using the full-back''s forward run and a supporting midfielder.', '4-3-3 shape in own half; goalkeeper starts with the ball, centre-back 4, right-back 2, midfielder 8, winger 7.', 'Centre-back 4 shows with a feint, receives from the keeper and turns; when he can play, 2 runs forward in depth and 8 comes closer. If 2 receives the exercise ends; if 8 receives he turns and plays 2 on the overlap while 7 drifts inside to open space.', NULL, NULL, 'Receive after a dummy; open body to turn.', NULL, NULL, NULL, 'full pitch (shadow play in formation)', NULL, NULL, NULL, false, true, true, NULL, 270),
  ('4-3-3 build-up with switch of play', 'passing_unopposed', 'unopposed', 'in_possession', 80, 80, '4.9 (diagram 64)', NULL, 'Play out from the back and switch to the far side when the near full-back is shut down.', '4-3-3 shape in own half; goalkeeper, centre-backs 4 and 6, full-backs 2 and 3, midfielders, wingers.', 'Full-back 2 tries to dribble out, is closed down and passes back to 4; 4 turns and drives inside before switching to the far full-back 3 running deep as midfielder 10 comes closer; if 4 is pressed, 6 supports behind him.', NULL, NULL, NULL, NULL, NULL, NULL, 'full pitch (shadow play in formation)', NULL, NULL, NULL, false, true, true, NULL, 280),
  ('4-3-3 build-up through the holding midfielder', 'passing_unopposed', 'unopposed', 'in_possession', 81, 81, '4.10 (diagram 65)', NULL, 'Build out through the central midfielder (pivot) to find the attacking midfielder between the lines.', '4-3-3 shape in own half; goalkeeper, centre-back 4, holding midfielder 5, midfielder 10, full-back 3, winger 11.', '5 comes off his marker, takes the pass from 4, turns and plays 10 cutting in behind the opposing midfield; 3 covers the space left and winger 11 comes inside to create room.', NULL, 'Variation: 5 cannot turn, so 10 comes to support, receives from 5 and then picks 3 or the cutting 11.', NULL, NULL, NULL, NULL, 'full pitch (shadow play in formation)', NULL, NULL, NULL, false, true, true, NULL, 290),
  ('Beat the press with a ball into the striker', 'passing_unopposed', 'unopposed', 'in_possession', 82, 82, '4.11 (diagrams 66-68)', NULL, 'When pressed near the ball, escape with a long forward pass to the centre-forward and play off him.', '4-3-3 shape; goalkeeper and back line building, full-back 2 shut down, centre-forward 9 and wingers 7 and 11 ahead.', '2 dribbles, is closed down and passes back to centre-back 4, whose only option is long to 9 after 9 shakes his marker with a fake run. If the wingers have run beyond 9, 4 plays longer to them. If not: with midfielders far away, 9 is supported by the facing winger while the other winger cuts in and 10 or 3 fill space; with midfielders close, they take the lay-off and release the wingers cutting in while 8 or 10 move into space.', NULL, 'Different responses depending on winger depth and midfield distance (diagrams 67, 68).', NULL, NULL, NULL, NULL, 'full pitch (shadow play in formation)', NULL, NULL, NULL, true, true, true, NULL, 300),
  ('Beat the press with a ball in behind for striker', 'passing_unopposed', 'unopposed', 'in_possession', 83, 83, '4.12 (diagram 69)', NULL, 'Same escape from pressure as 4.11, but the centre-forward receives running in behind.', 'As 4.11: 4-3-3 shape, goalkeeper and back line under pressure, 9 and both wingers ahead.', 'The long pass goes into space behind for 9 to run onto; the near-side winger 7 supports 9 immediately while the far winger 11 attacks depth.', NULL, NULL, 'One winger supports, the other goes in depth; keep the ball to let the team move up, or attack quickly if the defence is disorganised.', NULL, NULL, NULL, 'full pitch (shadow play in formation)', NULL, NULL, NULL, true, true, true, NULL, 310),
  ('Winger penetration: triangle and 1v1 options', 'combination', 'passive', 'in_possession', 84, 86, '4.13 (diagrams 70-73)', NULL, 'Options for the winger to get past his full-back: wall pass with the striker, 1v1 inside or outside, or a supporting pass.', '4-3-3 attacking third; winger 7 wide against an opposing full-back, centre-forward 9, far winger 11, midfielders 8 and 10.', 'Winger runs off the back of the full-back to receive to feet; with space he plays a one-two with 9 and then crosses for 9 and 11, or slips in 11 cutting in, finds 10 arriving, or shoots.', NULL, 'Alternatives: 1v1 beating the defender inside to serve 9/11 cutting in, or outside to cross (70b, 70c); winger cannot turn so plays to a supporter and the move continues with 7 running long and 9 short (72); when the winger is doubled, pass or split the two defenders (73).', 'Use the one-two when the defender slides behind to block 7; 9 and his marker screen the full-back.', NULL, NULL, NULL, 'full pitch (shadow play in formation)', NULL, NULL, NULL, true, false, true, NULL, 320),
  ('Overlap by midfielder or full-back (1-2-3)', 'combination', 'passive', 'in_possession', 87, 88, '4.14 (diagrams 74-76)', NULL, 'Create a 2v1 on the flank by overlapping the winger, with a third player as support.', 'Attacking half; winger 7 wide with ball at feet, midfielder 8 and full-back 2 behind, centre-forward 9, back four behind halfway.', '8 passes to 7 and overlaps; 7 can play 9 who sets 8 for a cross, or combine inside with 9 if 8 cannot be found wide. If 7 is shut down, a third player (5 or 2) supports, 8 accelerates past and receives behind 7 to cross - the 1-2-3 move.', NULL, 'If the full-back 2 makes the overlap, 8 becomes the third supporting player (diagram 76).', 'Overlap can drag defenders to the ball side and open the far side for runners.', NULL, NULL, NULL, 'full pitch (shadow play in formation)', NULL, NULL, NULL, true, false, true, NULL, 330),
  ('Winger''s diagonal run inside', 'combination', 'unopposed', 'in_possession', 89, 89, '4.15 (diagrams 77-78)', NULL, 'Tightly marked winger cuts diagonally inside so another player can attack the space left wide.', 'Attacking half; winger 7 wide and tightly marked, midfielder 8 and full-back 2 behind him, forwards 9 and 11, attacking midfielder 10.', 'With 8 on the ball, 7 cuts inside and 2 runs into the wide space. If 7 receives he serves 9 or 11 cutting in with 10 arriving, or shoots; if 2 receives he triangles with 7 and crosses, or 7 runs across in front and 2 crosses.', NULL, 'Variation: 2 in possession, 8 takes the space left by 7 and has the same options (diagram 78).', NULL, NULL, NULL, NULL, 'full pitch (shadow play in formation)', NULL, NULL, NULL, true, false, true, NULL, 340),
  ('Centre-forward checking and setting', 'combination', 'passive', 'in_possession', 90, 91, '4.16 (diagrams 79-81)', NULL, 'Centre-forward''s movements to receive into feet depending on whether his marker presses tight or stays off.', 'Attacking half; centre-forward 9, wingers 7 and 11, midfielders 5, 8, 10; back four in reserve.', 'Two cases: the defender presses so 9 lays off and runs; or the defender stays off so 9 turns. 9 receives from 5, sets or turns, and the wingers and midfielders cut in towards goal to receive the next pass or shoot.', NULL, 'Diagram 81: 9 takes it from 8, can only play back to 5, and 5 then serves the wingers and the wide midfielders cutting in.', NULL, NULL, NULL, NULL, 'full pitch (shadow play in formation)', NULL, NULL, NULL, true, false, true, NULL, 350),
  ('Back three slides with the ball', 'defending', 'passive', 'out_of_possession', 99, 100, '5.1 To rationally fill the space (diagrams 82-86)', NULL, 'Back three shift as a unit to cover the space near the ball without opening the far side.', 'Keeper plus three defenders in front of goal; three attackers A, B, C spread across the pitch about 20 yards from the line, passing between them.', 'A, B and C pass across the line and the three defenders slide towards the new ball carrier, the far defender stopping at the far post. Then the attackers dribble right, left, forward or back and the line moves across and steps up or drops accordingly.', 'Defenders keep about 20 yards from the ball, so they have time to react to a long pass.', 'Add a midfield four in front shifting with the defence; then add the forwards to complete the team. Repeat with the ball carrier moving around.', 'Far defender never goes past the far post; step up or drop (tactical run) depending on where the ball travels.', '3 defenders + GK v 3 servers, building to a full team', 7, 14, 'Half pitch', NULL, NULL, NULL, true, true, false, NULL, 360),
  ('Back three press and cover triangle', 'defending', 'passive', 'out_of_possession', 101, 104, '5.2 Coming out and covering the opposing player in possession (diagrams 87-95)', NULL, 'One defender steps out to the ball while the other two cover, forming a triangle.', 'Keeper plus back three facing three (later four) servers A, B, C, D across the field in front of the defence.', 'The coach points to the server who has the ball, or the servers pass on the coach''s whistle, then freely; the nearest defender comes out to close him and the other two drop and cover. Central ball: the middle defender closes and both sides cover.', NULL, 'Add one forward on the defensive line, then two, who must be marked while still covering; add a midfield four; then two forwards on the line plus one or two players in the midfield line. Read the ball: if the carrier can play forward, defenders drop and mark; if not, mark tighter and midfield presses harder.', 'Wide midfielder on the ball side judges whether to drop in as a fourth defender; when marking two attackers, guard the one nearer goal.', '3 defenders + GK (+4 midfielders) v 3-4 servers + 1-3 forwards', 7, 16, 'Half pitch', NULL, NULL, NULL, true, true, false, NULL, 370),
  ('Doubling up with a back three', 'defending', 'passive', 'out_of_possession', 110, 111, '5.6 Doubling the marking (diagrams 101-105)', NULL, 'Defenders and midfielders double up on the ball receiver while the rest of the unit balances.', 'Keeper, back three and a midfield four (or five) facing three attackers A, B, C; the coach starts with the ball in midfield.', 'The coach plays the ball wide or into the middle; the nearest defender closes the receiver, the nearest midfielder doubles, the others cover and slide. Central ball: the middle defender closes, a central midfielder doubles, the outside defenders cover.', NULL, 'Midfield of five: on a wide ball the wide defender and wide midfielder double; if wide men are too far or late, a central midfielder doubles instead and the far wide man tucks in to balance.', 'Close, double, cover, balance; the player who leaves his line must be replaced.', '3 defenders + 4-5 midfielders + GK v 3 attackers + coach', 11, 13, 'Half pitch', NULL, NULL, NULL, true, true, false, NULL, 380),
  ('3v3 plus keeper, offside trap and counter', 'defending', 'opposed', 'out_of_possession', 112, 112, '5.7 A few training exercises (diagram 106)', NULL, 'Back three defend a 3v3, using the offside line, then break out when they win it.', 'Area about 30 m deep from the goal line, penalty-box width; keeper and three defenders v three attackers A, B, C; two small goals (about 3 m) on the side lines at the 30 m line; coach serves from the top.', 'The coach plays into A, B or C, who attack the big goal. If the defenders win the ball they counter by spreading wide to score in either side goal.', 'Attackers score in the big goal; defenders score in the small side goals.', 'Repeat with the defensive line set just in front of the halfway line.', 'Step up together to catch attackers offside; spread wide fast when the ball is won.', '3v3 + GK + coach', 8, 8, '30 m x box width', 30.0, NULL, NULL, true, true, true, NULL, 390),
  ('9v7 plus keeper, defend and counter', 'phase_of_play', 'overload', 'out_of_possession', 112, 113, '5.7 A few training exercises (diagrams 107-108)', NULL, 'A 3-4 defensive block defends an overload and counters on winning the ball.', 'Half pitch; keeper and seven defenders set as 3-4 against nine attackers; three small goals (about 3 m) on the halfway line, one central and one at each touchline.', 'The nine attackers try to score in the big goal; when the seven win the ball they counter into one of the three small goals on the halfway line.', 'Attackers to the big goal; defenders to the three small goals.', 'Set the nine attackers in the shape you expect from the next opponent. For a 3-5-2 defence play 10v8 (3-5) plus keeper, with the small goals about 10 m past halfway.', NULL, '9v7 + GK (10v8 + GK)', 17, 19, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 400),
  ('3-5-2 pattern: striker''s flick-on', 'combination', 'unopposed', 'in_possession', 123, 123, '6.1 3:5:2 Header of the forward (diagrams 109-110)', NULL, 'Rehearse a build-up from the back that ends with the striker heading on for runners.', '3-5-2 shape unopposed on a full pitch, attacking one goal with a keeper.', 'Centre-back feeds the central midfielder, who checks off his marker and plays back; the centre-back plays long to the striker, who also feints first. The striker heads on as the wide men run in behind and the second forward supports.', NULL, 'A wide midfielder supports the striker instead, the second forward runs in behind him and the other wide man fills the space left.', 'Feint before receiving; runners time their moves off the header.', '10 outfield (3-5-2) + GK', 11, 11, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 410),
  ('3-5-2 pattern: forward''s set and run', 'combination', 'unopposed', 'in_possession', 124, 124, '6.2 Penetrating movement of the forward (diagram 111)', NULL, 'Rehearse a forward dropping to link play while his partner attacks the space behind.', '3-5-2 shape unopposed attacking one goal.', 'Centre-back plays into the striker after a feint; the central midfielder supports and gets the ball back to the striker. The other forward cuts in behind as both wide midfielders push high up the pitch.', NULL, NULL, 'Check away before receiving; second forward runs off the first.', '10 outfield (3-5-2) + GK', 11, 11, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 420),
  ('3-5-2 pattern: wide link man', 'combination', 'unopposed', 'in_possession', 125, 125, '6.3 Attacking with a link man (diagrams 112-113)', NULL, 'Rehearse play through the central midfielder out to the wide link man to get in behind.', '3-5-2 shape unopposed attacking one goal.', 'A centre-back feeds a midfielder who receives after a feint and plays to the central midfielder; he passes forward to the wide link man. The striker cuts in, the other forward goes wide and the far wide man comes in from the far side, all aiming to get behind the back line.', NULL, 'The forward swaps places with the link man, the striker attacks the space he left and the far wide man attacks the blind side.', NULL, '10 outfield (3-5-2) + GK', 11, 11, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 430),
  ('3-5-2 pattern: link man inside', 'combination', 'unopposed', 'in_possession', 126, 126, '6.4 Attacking with the link man inside (diagrams 114-115)', NULL, 'Rehearse a wide pair rotating to free the wide man, with a midfielder filling the centre.', '3-5-2 shape unopposed attacking one goal.', 'The wide pair swap, one coming inside and one going out wide to receive in space. As neither forward drops, the holding midfielder steps into the middle under the forwards to take the ball.', NULL, 'If the forwards are marked tight inside, they rotate with a criss-cross to get free and the forward without the ball cuts in towards goal.', NULL, '10 outfield (3-5-2) + GK', 11, 11, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 440),
  ('3-5-2 three-player combination to cross', 'combination', 'unopposed', 'in_possession', 127, 127, '6.5 Combination with three players (diagrams 116-117)', NULL, 'Rehearse a three-player move that frees the wide midfielder to cross.', '3-5-2 shape unopposed attacking one goal with a keeper.', 'The link man comes towards the ball-carrying defender while staying wide; a midfielder runs into the wing space; the striker shows short after a feint and plays to the central midfielder, who sends the wide runner in to cross. The other forward makes a diagonal run and the far wide man arrives in the box.', NULL, 'With no support the striker turns inside and plays the other forward; a midfielder fills the free space and the wide man cuts in from the right.', NULL, '10 outfield (3-5-2) + GK', 11, 11, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 450),
  ('3-5-2 pattern: central midfielder drops', 'combination', 'unopposed', 'in_possession', 128, 128, '6.6 Coming out on the attacking center half (diagrams 118-119)', NULL, 'Rehearse the playmaker dropping to receive from the back and the link man coming inside.', '3-5-2 shape unopposed attacking one goal.', 'The central midfielder drops with a feint to get the ball from the right centre-back; the right midfielder goes wide beneath the advanced link man. Seeing no forward come short, the link man comes inside to receive and holds the ball until teammates arrive.', NULL, 'The link man plays a one-two with the striker first, letting a midfielder and the other forward swap places.', 'Hold the ball to buy time for support runs.', '10 outfield (3-5-2) + GK', 11, 11, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 460),
  ('Midfielder switches play via attacking center half', 'combination', 'unopposed', 'in_possession', 129, 129, '6.7 Change of direction of the ball by the attacking center half (diagrams 120-121)', NULL, 'Rehearse a team pattern where the wide midfielder changes the direction of play through the attacking center half and forwards rotate to open space.', 'Full pitch shadow play in the book''s 3-4-3 shape, attacking one goal, no opponents.', 'Left midfielder 6 receives, controls and carries the ball inside using the link man 10''s movement, then passes in; 11 pushes on as the attacking center half prepares to receive, forward 9 clears space and 8 makes a diagonal run from the right.', NULL, 'Variation: 6 is supported by 11 who receives after a feint, 11 lays to attacking center half 4 who plays link man 10 in on the run.', 'Timing of the clearing runs so the next receiver has space.', 'team shape (10 outfield)', NULL, NULL, 'full pitch', NULL, NULL, NULL, true, false, true, NULL, 470),
  ('Back three switching to lateral or vertical posts', 'passing_unopposed', 'unopposed', 'in_possession', 130, 131, '6.8 3:4:3 Exercises to improve the technical aspect of 3:4:3 (diagrams 122-126)', NULL, 'Train the three defenders'' passing technique and body shape when switching the play and finding lateral or vertical support in a 3-4-3.', 'Defenders 2, 5 and 3 in their positions on the pitch; cone posts mark lateral support spots (A, B) and vertical support spots (C, D, E) in midfield.', 'The back three move the ball across, each having only two passing options, and play into a lateral or vertical post; if neither option is on they go long. Gradually more players join in their positions until the whole team is linked in passing chains.', 'Each defender has only two passing options.', 'Add players line by line until the full 3-4-3 chain is in place; speed up execution, or run it slower as a ball warm-up.', 'Coach checks receiving body position and line of sight, corrects technique and the follow-up movement of the other defenders.', '3 defenders building to full team', 3, 11, 'full pitch', NULL, NULL, NULL, false, false, true, NULL, 480),
  ('Goalkeeper throw starts wide cross pattern', 'combination', 'unopposed', 'in_possession', 132, 134, '6.9 Hand pass of the goalkeeper (diagrams 127-132)', NULL, 'Rehearse building from a goalkeeper hand pass to a wide cross or shot, with box occupation and covering positions.', 'Full pitch shadow play, 3-4-3 shape with goalkeeper, attacking the far goal.', 'Goalkeeper throws to 5, 5 to 2, 2 plays vertically to 10; 10 comes inside and finds 9, creating space for 7 to run in behind; 9 receives after a feint and opens up to 7 who crosses to 9, 11 and 10 attacking near post, far post and penalty spot while 4, 6, 8 and the back three hold covering positions.', NULL, 'Variation: 9 does not go to 7 but lays back to 10 who shoots. Variation 1: 9 passes to 10 who plays 11 into the box.', 'Three reference points in the box (near post, far post, penalty spot); midfield and back line cover in case the ball is lost.', 'full team shape incl. GK', NULL, NULL, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 490),
  ('Cable movement: link man drops, wide cross', 'combination', 'unopposed', 'in_possession', 135, 135, '6.10 "Cable" movement (diagrams 133-134)', NULL, 'Rehearse the link man dropping toward the full back to free space behind for a pass into the striker and a cross from the winger.', 'Full pitch shadow play from the goalkeeper in the 3-4-3 shape, attacking the far goal.', 'Goalkeeper starts play to the back line and on to 2; 10 moves towards 2, emptying the space behind him; 2 passes to 9 who feints, then controls or lays it off to 7 who crosses.', NULL, NULL, 'Teammates take preventive covering positions behind the ball.', 'full team shape incl. GK', NULL, NULL, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 500),
  ('1v1 tackling with a still ball', 'one_v_one', 'opposed', 'out_of_possession', 141, 141, '7.5 Exercise A (diagram 135)', NULL, 'Practise the tackle technique on a stationary ball with both feet.', 'Pairs, A and B facing each other over a still ball.', 'A and B contest the ball, alternating right and left foot.', NULL, NULL, 'Get close to the ball, standing foot nearly parallel to it, weight forward so the tackle has force.', 'pairs', 2, 2, NULL, NULL, NULL, NULL, false, false, false, NULL, 510),
  ('Retreating defender jockeys a dribbler', 'one_v_one', 'passive', 'out_of_possession', 141, 141, '7.5 Exercise B (diagrams 136-137b)', NULL, 'Train the defender''s backward movement and positioning against a dribbler who goes left or right.', 'Pairs in a channel: attacker A with ball, defender B in front.', 'A dribbles at B, who backs off and adjusts his position depending on which side A goes.', NULL, 'Repeat facing right and left; then the dribbler pushes the ball long towards the inside.', 'Weight on the balls of the feet, eyes on the ball, steer the attacker to the outside.', 'pairs', 2, 2, NULL, NULL, NULL, NULL, false, false, true, NULL, 520),
  ('1v1 when attacker knocks the ball past', 'one_v_one', 'opposed', 'out_of_possession', 141, 141, '7.5 Exercise C (diagrams 138-139)', NULL, 'Teach the defender how to deal with an attacker who plays the ball past him and runs.', 'Pairs: attacker A dribbling, defender B in front.', 'A tries to beat B by knocking the ball long; B, having kept the ball from getting too close, wins it by getting to it first.', NULL, 'Variation: B has let the ball get too close, so he must cut across the attacker''s path and shield without fouling.', 'Keep distance so the ball never gets too close; if it does, block the runner''s line legally.', 'pairs', 2, 2, NULL, NULL, NULL, NULL, false, false, true, NULL, 530),
  ('Contain the receiver from the inside', 'one_v_one', 'opposed', 'out_of_possession', 141, 141, '7.5 Exercise D (diagrams 140-141)', NULL, 'Train a defender to mark and contain a player receiving with his back to goal and time the tackle when he turns.', 'Three players: server A, receiver B, defender C marking B from the inside.', 'A passes to a stationary B; C contains from the inside and B plays back to A. Repeat facing right and left.', NULL, 'Variation: B comes towards the ball to receive, C closes him down and picks the moment to tackle as B tries to turn.', 'Stay goal side and inside; tackle when the receiver is half turned and covering the ball least.', '3', 3, 3, NULL, NULL, NULL, NULL, false, false, true, NULL, 540),
  ('Marking adjusts to the passer''s vision', 'one_v_one', 'opposed', 'out_of_possession', 142, 142, '7.5 Exercise E (diagram 142)', NULL, 'Teach the marker to tighten or loosen marking depending on whether the ball carrier can see his opponent.', 'Groups of three: ball carrier A, attacker B and defender C marking B from the inside.', 'A turns his body or head so he can or cannot see B; C changes his marking distance accordingly. Repeat facing right and left.', NULL, NULL, 'Tight when the ball carrier can play forward, looser when he cannot see.', '3', 3, 3, NULL, NULL, NULL, NULL, false, false, false, NULL, 550),
  ('Central 1v1 to goal with counterattack', 'one_v_one', 'opposed', 'in_possession', 142, 142, '7.5 Exercise F (diagrams 143-145)', NULL, 'Live 1v1 duels in front of goal for both attacker and defender, with a counterattack if the defender wins it.', 'Channel about 10m wide and 20m long in front of a goal with goalkeeper; attacker at the far end, defender near the goal.', 'When the attacker sets off with the ball the defender engages; the attacker must exit the opposite side and shoot or beat the keeper 1v1. If the defender wins it he counterattacks to the attacker''s start line, where he can only be stopped 1v1 by the attacker.', 'Defender scores by dribbling over the starting line.', 'V1: attacker receives a pass to start, defender may start from left or right. V2: wide 1v1 with counterattack, attacker can exit either side. V3: high wide 1v1. V4: repeat all with the receiver back to goal.', NULL, '1v1 + GK', 3, 3, '10m x 20m', 20.0, 10.0, NULL, true, true, true, NULL, 560),
  ('Model game: fixed pairs plus free player', 'small_sided_game', 'opposed', NULL, 142, 143, '7.5 Model Game', NULL, 'Practise all forms of 1v1 marking in a game and learn to read and recover to your opponent.', 'Two teams in fixed marking pairs with two goalkeepers; each team has one free player who stays in his own half.', 'Each player may only challenge, and be challenged by, his direct opponent; the free player cannot be tackled when in possession and is the only one who can engage an unmarked opponent.', 'Pairs only duel each other; free player stays in own half and is untouchable on the ball.', NULL, 'Never get left out of your duel; read the marking correctly; when going to the ball, get back to your man.', 'set pairs + 2 free players + 2 GK', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 570)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'kindle-soccer-modern-tactics') b;
INSERT INTO schema_migrations (filename) VALUES ('5011-exercises-book-kindle-soccer-modern-tactics.sql') ON CONFLICT DO NOTHING;
COMMIT;
